def best_rects(G, top=12):
    best = []
    R,C = G.shape
    for color in np.unique(G):
        M = (G==color).astype(int)
        for r0 in range(R):
            colsum = np.zeros(C, int)
            for r1 in range(r0, R):
                colsum += M[r1]
                h = r1-r0+1
                run=0; bestlen=0; startc=0
                for c in range(C):
                    if colsum[c]==h:
                        run+=1
                        if run>bestlen: bestlen=run; startc=c-run+1
                    else: run=0
                if bestlen>0:
                    best.append((h*bestlen, color, r0, startc, r1, startc+bestlen-1))
    best.sort(reverse=True)
    return best[:top]
for b in best_rects(G): print(b)

